head.script:
scwin.onpageload = function() {
    dataList1.insertRow();
    var rJSON = dataList1.getRowJSON(0);
    var jsonData = [];
    for (var i = 0; i < 3; i++) {
        var tmp = {};
        for (var item in rJSON) {
            if (item == "rowStatus") continue;
            tmp[item] = item + "_" + i;
        }
        jsonData.push(tmp);
    }
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col1");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col1", visible);
};
scwin.trigger2_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col2");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col2", visible);
};
scwin.trigger3_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col3");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col3", visible);
};
scwin.trigger4_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col4");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col4", visible);
};
scwin.trigger5_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col5");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col5", visible);
};
scwin.trigger6_onclick = function(e) {
    var visible = gridView1.getColumnVisible("col6");
    visible = visible ? false : true;
    gridView1.setColumnVisible("col6", visible);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal1 = function() {
    gridView1.setColumnOrder(["col2", "col1", "col4", "col6", "col3", "col5"]);
}
scwin.setVal2 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_1', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_column11').innerText == 'name2'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_column13').innerText == 'name1'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_0').style.backgroundColor == 'rgb(252, 167, 60)'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
